from collections import Counter
import itertools


def task_func(d):
    """
    Count how often each integer occurs across all lists in the dictionary's values.

    Parameters:
        d (dict): A dictionary whose values are lists of integers.

    Returns:
        dict: A dictionary mapping each integer found in the lists to the number
              of times it occurs across all lists.
    """
    flattened = itertools.chain.from_iterable(d.values())
    return dict(Counter(flattened))


if __name__ == "__main__":
    sample = {"a": [1, 2, 3, 1], "b": [3, 4, 5], "c": [1, 2]}
    print(task_func(sample))  # {1: 3, 2: 2, 3: 2, 4: 1, 5: 1}
    print(task_func({}))      # {}
```

`itertools.chain.from_iterable` joins all the lists into one stream without building an intermediate list. `Counter` then counts each integer, and the result is converted to a plain `dict`. An empty input dictionary, or empty lists, return `{}`.
